/* Spawns a moby of class 0x75E and initialises its data. */
char *spawn_spawner_egg(int owner, void *pos, void *rot, unsigned char a, unsigned char b) {
    char *m = (char *)CreateMoby(0x75E);
    if (m) {
        struct SpawnerEggVars *d = (struct SpawnerEggVars *)((Moby *)m)->pvars;
        *(int *)&d->owner = owner;
        qcopy(m + 0x10, pos);
        qcopy(&d->vel, rot);
        ((Moby *)m)->rot.x = random_float_between(-3.1415927f, 3.1415927f);
        ((Moby *)m)->rot.y = random_float_between(-3.1415927f, 3.1415927f);
        d->unk_14 = 0;
        d->timer = scale_ticks(500);
        ((Moby *)m)->update_dist = 0xFF;
        ((Moby *)m)->draw_dist = 0x40;
        m[0x31] = 1;
        m[0x20] = 0;
        ((Moby *)m)->scale = *(float *)(*(char **)(m + 0x24) + 0x24) * 0.3f;
        d->slot = b;
        d->kind = a;
        d->unk_1B = 0;
        moby_build_matrix(m);
    }
    return m;
}
extern void DeleteMoby(void *);

/* Clear the egg's slot in its live spawner (class 0x75D), then delete the egg moby. */
void remove_spawner_egg(void *moby, char *data)
{
    char *other = *(char **)(data + 0x10);
    if (other != 0 && ((Moby *)other)->oclass == 0x75D &&
        (unsigned char)other[0x20] != 0xFE && (unsigned char)other[0x20] != 0xFD) {
        int index = (unsigned char)data[0x1C];
        char *base = ((char *)((Moby *)other)->pvars);
        base += index * 4;
        *(int *)(base + 0xB0) = 0;
    }
    DeleteMoby(moby);
}
typedef int OvlQuad __attribute__((mode(TI)));
typedef u32 u128 __attribute__((mode(TI), aligned(16)));
extern f32 fast_atan2(f32, f32);
void remove_spawner_egg(void *moby, char *data);
typedef struct {
    u8 pad0[0x18];
    s32 moby; /* 0x18: passed to FUN_002141f8 (reads moby+0x34, moby+0x78); 0 when no moby was hit */
    s32 unk1C; /* 0x1C: > 0 gates copying point and the normal into the hero (shared/ui/help/00226f10.c) */
    union {
        OvlQuad q;
        f32 f[4];
    } point; /* 0x20: f[2] is read as the ground height */
    u8 pad30[0x10]; /* 0x30: position after push-out (copied into hero.motion.pos) */
    f32 normal_x; /* 0x40: start of the surface normal; its angle is tested against 50 degrees (0.87266463) */
    f32 normal_y; /* 0x44: FUN_001f9e90 (atan2) of normal_x, normal_y is stored in the hero */
    f32 normal_z; /* 0x48: ledge probes compare atan2(normal_z, xy length) with 20 degrees */
} CollisionHit;
typedef struct {
    Vec4 vel; /* 0x00 */
    struct Moby *owner; /* 0x10: class 0x75D spawner; its pvars hold the bubble list at 0xB0 */
    struct Moby *held; /* 0x14: from FUN_L09_0030a778 when the bubble settles */
    s16 life; /* 0x18 */
    u8 unk1A;
    u8 sound_delay; /* 0x1B */
    u8 slot; /* 0x1C: index in the owner's bubble list */
} BubbleVars;
typedef struct {
    u8 pad0[0xB0];
    struct Moby *bubbles[20];
} BubbleOwnerVars;
